/* Money */
const M = (a, c, o) => new Money(a, c, o);
n++; throwsEq("money-minorfrac", () => M(1, "USD", { minorDigits: 2.5 }), "minorDigits must be an integer");
function throwsEq(label, fn, msgPart) {
    n++;
    try { fn(); fail(label, "no throw", "throw ~" + msgPart, label); }
    catch (e) { if (msgPart && e.message.indexOf(msgPart) < 0) fail(label, e.message, "~" + msgPart, label); }
}
