/* allocate exact-sum invariant, 300 random splits incl. indivisible remainders */
{
    const cur = ["USD", "JPY", "BHD", "XYZ"];
    for (let i = 0; i < 300; i++) {
        const c = cur[i % 4];
        const amt = (Math.floor(Math.random() * 1e9) + 1) * (i % 2 ? -1 : 1);
        const k = (i % 7) + 1;
        const shares = [];
        for (let j = 0; j < k; j++) shares.push(Math.floor(Math.random() * 1000) + (j % 5 === 0 ? 0 : 1));
        if (shares.every((s) => s === 0)) shares[0] = 1;
        const parts = M(amt, c).allocate(shares);
        let s = 0;
        for (const p of parts) s += p.amount();
        n++;
        if (s !== amt) fail("allocate-sum", s, amt, amt + " / " + shares);
    }
}
